"""Figures for the m3541 vacuous-guard audit.

Every number is read from a machine-produced artefact, never typed by hand:

* ``outputs/finite_depth_energy_identity/convergence.json`` -- regenerated by
  ``python -m tensorbem.benchmarks.finite_depth_energy_convergence``;
* ``outputs/ursell_reproducibility_study.json`` -- regenerated by
  ``python examples/ursell_reproducibility_study.py``;
* ``docs/m3541/baseline_skip_run.log`` -- the pytest ``-rs`` transcript of the
  same two modules executed against a clean ``git archive HEAD`` checkout.

Usage::

    PYTHONPATH=src python3 docs/m3541/make_figures.py
"""

from __future__ import annotations

import json
import re
from pathlib import Path

import matplotlib

matplotlib.use("Agg")
import matplotlib.pyplot as plt  # noqa: E402
import numpy as np  # noqa: E402

ROOT = Path(__file__).resolve().parents[2]
OUT = Path(__file__).resolve().parent / "figures"
FD = ROOT / "outputs" / "finite_depth_energy_identity" / "convergence.json"
URSELL = ROOT / "outputs" / "ursell_reproducibility_study.json"
BASE_LOG = Path(__file__).resolve().parent / "baseline_skip_run.log"


def skip_counts(log: Path) -> dict[str, int]:
    """Count ``SKIPPED`` lines per test module in a pytest ``-rs`` transcript."""
    counts: dict[str, int] = {}
    for line in log.read_text().splitlines():
        match = re.search(r"SKIPPED \[\d+\] (tests/\S+?\.py)", line)
        if match:
            counts[match.group(1)] = counts.get(match.group(1), 0) + 1
    return counts


def module_skips(log: Path) -> dict[str, int]:
    counts: dict[str, int] = {}
    for line in log.read_text().splitlines():
        match = re.search(r"SKIPPED \[\d+\] (tests/\S+?\.py):", line)
        if match:
            counts[match.group(1)] = counts.get(match.group(1), 0) + 1
    return counts


def figure() -> Path:
    fd = json.loads(FD.read_text())
    ur = json.loads(URSELL.read_text())
    skips = module_skips(BASE_LOG)

    fig, axes = plt.subplots(1, 3, figsize=(15.5, 4.4))

    # --- (a) finite-depth energy identity: offset vs panels, three depths ----
    ax = axes[0]
    labels = {"shallow": "h/a=3.2", "medium": "h/a=5.0", "deep": "h/a=20.0"}
    linestyles = {"shallow": "o-", "medium": "s-", "deep": "^-"}
    for label in labels:
        rows = sorted(
            (
                r
                for r in fd["rows"]
                if r["depth_label"] == label and r["motion"] == "heave"
            ),
            key=lambda r: r["panels"],
        )
        panels = np.array([r["panels"] for r in rows], dtype=float)
        offs = np.array([abs(r["energy_offset"]) for r in rows])
        ax.loglog(panels, offs, linestyles[label], label=labels[label])
    ax.axhline(1.0e-2, color="tab:red", ls=":", lw=1.2, label="1% acceptance")
    ax.set_xlabel("panels $N$ (constant panels)")
    ax.set_ylabel("|$B_{far}/B_{near}-1$|")
    ax.set_title("finite-depth energy identity: 1% offset closes at 1st order")
    ax.grid(True, which="both", alpha=0.3)
    ax.legend(fontsize=8)

    # --- (b) Ursell panel sweep against the multipole reference -------------
    ax = axes[1]
    sweep = sorted(ur["panel_sweep"], key=lambda r: r["panels"])
    panels = np.array([r["panels"] for r in sweep], dtype=float)
    a_err = np.array([r["added_mass_error"] for r in sweep])
    b_err = np.array([r["damping_error"] for r in sweep])
    ax.loglog(panels, a_err, "o-", label="added mass")
    ax.loglog(panels, b_err, "s-", label="damping")
    ax.loglog(panels, a_err[0] * (panels[0] / panels), "k--", lw=1.0, label="$O(h)$ guide")
    ax.axhline(3.0e-2, color="tab:red", ls=":", lw=1.2, label="3% acceptance")
    for x, y in zip(panels, a_err):
        ax.annotate(f"{y:.2e}", (x, y), textcoords="offset points", xytext=(4, -10),
                    fontsize=7)
    ax.set_xlabel("panels $N$")
    ax.set_ylabel("relative error vs Ursell multipole")
    ax.set_title(f"Ursell cylinder radiation, $ka={ur['case']['ka']}$ (regenerated)")
    ax.grid(True, which="both", alpha=0.3)
    ax.legend(fontsize=8)

    # --- (c) guard liveness before/after ------------------------------------
    ax = axes[2]
    modules = [
        "tests/test_finite_depth_energy_convergence.py",
        "tests/test_ursell_reference_pinning.py",
    ]
    short = ["finite_depth_energy\n_convergence", "ursell_reference\n_pinning"]
    before = [skips.get(m, 0) for m in modules]
    x = np.arange(len(modules))
    ax.bar(x - 0.19, before, width=0.38, color="tab:red",
           label="skipped in clean checkout (before)")
    ax.bar(x + 0.19, [0, 0], width=0.38, color="tab:green",
           label="skipped after committing artefacts")
    for xi, value in zip(x, before):
        ax.text(xi - 0.19, value + 0.06, str(value), ha="center", fontsize=9)
    ax.set_xticks(x, short, fontsize=8)
    ax.set_ylabel("test functions silently skipped")
    ax.set_ylim(0, max(before) + 1.2)
    ax.set_title("guards that never ran: 5 → 0")
    ax.grid(True, axis="y", alpha=0.3)
    ax.legend(fontsize=8)

    fig.tight_layout()
    path = OUT / "gate_liveness.png"
    fig.savefig(path, dpi=105)
    plt.close(fig)
    return path


if __name__ == "__main__":
    OUT.mkdir(parents=True, exist_ok=True)
    print(figure())